// 수집 기간 계산: 전날 오전 6:30 ~ 당일 오전 6:30
const now = new Date();
const today = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 6, 30, 0);
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

// 네이버 뉴스 검색 API용 날짜 포맷
const formatDate = (d) => {
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}${month}${day}`;
};

// 검색 키워드 목록 (금융 관련)
const keywords = [
  '펀드 시장',
  '자산운용',
  '금융투자',
  'ETF 신규',
  '펀드 수익률',
  '자본시장'
];

return keywords.map(keyword => ({
  json: {
    keyword,
    startDate: formatDate(yesterday),
    endDate: formatDate(today),
    startDateTime: yesterday.toISOString(),
    endDateTime: today.toISOString()
  }
}));

// 네이버 뉴스 검색 결과 파싱 및 시간 필터링
const items = $input.all();
const allNews = [];
const seenUrls = new Set();

for (const item of items) {
  const data = item.json;
  const startDateTime = new Date(data.startDateTime || data.startDate);
  const endDateTime = new Date(data.endDateTime || data.endDate);

  if (data.items && Array.isArray(data.items)) {
    for (const news of data.items) {
      const pubDate = new Date(news.pubDate);

      // 전날 6:30 ~ 당일 6:30 범위 내의 뉴스만 필터링
      if (pubDate >= startDateTime && pubDate <= endDateTime) {
        // 제목에서 HTML 태그 제거
        const cleanTitle = news.title.replace(/<[^>]*>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');
        const cleanDesc = news.description.replace(/<[^>]*>/g, '').replace(/&quot;/g, '"').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>');

        // URL 기반 중복 제거
        const normalizedUrl = news.originallink || news.link;
        if (!seenUrls.has(normalizedUrl)) {
          seenUrls.add(normalizedUrl);
          allNews.push({
            json: {
              title: cleanTitle,
              description: cleanDesc,
              originallink: news.originallink,
              link: news.link,
              pubDate: news.pubDate,
              pubDateISO: pubDate.toISOString(),
              source: 'naver',
              keyword: data.keyword || ''
            }
          });
        }
      }
    }
  }
}

// 최신순 정렬
allNews.sort((a, b) => new Date(b.json.pubDateISO) - new Date(a.json.pubDateISO));

if (allNews.length === 0) {
  return [{ json: { noData: true, message: '수집된 네이버 뉴스가 없습니다.' } }];
}

return allNews;

// 네이버 뉴스와 구글 뉴스 중복 제거
// 입력 1: 네이버 뉴스 (구글시트 저장 결과)
// 입력 2: 구글 뉴스 목록

const naverNews = $('구글시트 네이버뉴스 저장').all();
const googleNews = $('구글뉴스 시트 읽기').all();

// 구글 뉴스 제목 Set 생성 (정규화된 제목 기준)
const normalizeTitle = (title) => {
  return title
    .replace(/[\s]+/g, ' ')
    .replace(/[^가-힣a-zA-Z0-9\s]/g, '')
    .trim()
    .toLowerCase();
};

const googleTitles = new Set();
for (const item of googleNews) {
  if (item.json.제목) {
    googleTitles.add(normalizeTitle(item.json.제목));
  }
}

// 중복되지 않는 네이버 뉴스만 필터링
const uniqueNaverNews = [];
for (const item of naverNews) {
  const normalizedTitle = normalizeTitle(item.json.title || item.json.제목 || '');

  // 제목 유사도 체크 (포함 관계도 확인)
  let isDuplicate = false;
  for (const gTitle of googleTitles) {
    if (normalizedTitle === gTitle || 
        normalizedTitle.includes(gTitle) || 
        gTitle.includes(normalizedTitle)) {
      isDuplicate = true;
      break;
    }
  }

  if (!isDuplicate) {
    uniqueNaverNews.push({
      json: {
        title: item.json.title || item.json.제목,
        description: item.json.description || item.json.내용,
        originallink: item.json.originallink || item.json.원문링크,
        link: item.json.link || item.json.네이버링크,
        pubDate: item.json.pubDate || item.json.발행일,
        source: 'naver',
        isDuplicate: false
      }
    });
  }
}

if (uniqueNaverNews.length === 0) {
  return [{ json: { noData: true, message: '중복 제거 후 발송할 네이버 뉴스가 없습니다.' } }];
}

return uniqueNaverNews;

// 뉴스 발송 메시지 포맷팅
const items = $input.all();

if (items.length === 1 && items[0].json.noData) {
  return [{ json: { type: 'news', news: [], count: 0, message: items[0].json.message } }];
}

const newsList = items.map(item => ({
  title: item.json.title,
  description: item.json.description,
  url: item.json.originallink || item.json.link,
  pubDate: item.json.pubDate,
  source: item.json.source
}));

return [{
  json: {
    type: 'news',
    news: newsList,
    count: newsList.length
  }
}];
